public class InnerCallAnalyticsCategorySentimentFilterFactory(Action<Humidifier.Transcribe.CallAnalyticsCategoryTypes.SentimentFilter> factoryAction = null) : SubResourceFactory<Humidifier.Transcribe.CallAnalyticsCategoryTypes.SentimentFilter>
{

    internal InnerCallAnalyticsCategoryRelativeTimeRangeFactory RelativeTimeRangeFactory { get; set; }

    internal InnerCallAnalyticsCategoryAbsoluteTimeRangeFactory AbsoluteTimeRangeFactory { get; set; }

    protected override Humidifier.Transcribe.CallAnalyticsCategoryTypes.SentimentFilter Create()
    {
        var sentimentFilterResult = CreateSentimentFilter();
        factoryAction?.Invoke(sentimentFilterResult);

        return sentimentFilterResult;
    }

    private Humidifier.Transcribe.CallAnalyticsCategoryTypes.SentimentFilter CreateSentimentFilter()
    {
        var sentimentFilterResult = new Humidifier.Transcribe.CallAnalyticsCategoryTypes.SentimentFilter();

        return sentimentFilterResult;
    }
    public override void CreateChildren(Humidifier.Transcribe.CallAnalyticsCategoryTypes.SentimentFilter result)
    {
        base.CreateChildren(result);

        result.RelativeTimeRange ??= RelativeTimeRangeFactory?.Build();
        result.AbsoluteTimeRange ??= AbsoluteTimeRangeFactory?.Build();
    }

} // End Of Class

